void edgeport_drain(struct edgeport_port *port, unsigned long timeout, int flush)
{
	struct tty_struct *tty = port->tty;
	DECLARE_WAITQUEUE(wait, current);

	spin_lock_irq(&port->lock);
	add_wait_queue(&port->wait, &wait);
	set_current_state(TASK_INTERRUPTIBLE);

	while (port->write_fifo_len > 0 && !port->disconnected) {
		if (timeout == 0)
			break;
		if (signal_pending(current))
			break;
		if (port->write_fifo_len > 0) {
			if (flush)
				edgeport_flush_buffer(port);
			break;
		}
		schedule_timeout(timeout);
		timeout = 0;
	}

	set_current_state(TASK_RUNNING);
	remove_wait_queue(&port->wait, &wait);
	spin_unlock_irq(&port->lock);
}

void edgeport_drain_data(struct edgeport_port *port, unsigned long timeout, int flush)
{
    struct tty_struct *tty = port->tty;
    wait_queue_t wait;
    unsigned long start_time;
    unsigned long drain_time;
    unsigned long baud_rate;
    unsigned int drain_size = 0;
    unsigned int chars_in_fifo = 0;
    int disconnected = 0;

    if (!tty)
        return;

    init_waitqueue_head(&wait);

    start_time = jiffies;
    drain_time = jiffies;

    spin_lock(&port->lock);

    if (port->disconnected) {
        spin_unlock(&port->lock);
        return;
    }

    if (flush)
        chars_in_fifo = port->write_fifo_size;

    spin_unlock(&port->lock);

    while ((chars_in_fifo > 0 || drain_size > 0) &&
           !disconnected &&
           (time_before(jiffies, start_time + timeout))) {
        add_wait_queue(&wait, &wait);
        set_current_state(TASK_INTERRUPTIBLE);

        if (port->disconnected)
            disconnected = 1;

        if (!disconnected && (chars_in_fifo > 0 || drain_size > 0)) {
            schedule_timeout(1);
        }

        set_current_state(TASK_RUNNING);
        remove_wait_queue(&wait, &wait);
    }

    if (flush)
        port->flush_write_fifo(port);

    spin_lock(&port->lock);

    if (!port->disconnected)
        port->drain(port, drain_time);

    spin_unlock(&port->lock);
}

void edgeport_drain_data(struct edgeport_port *port, unsigned long timeout, int flush)
{
    struct tty_struct *tty;
    wait_queue_t wait;
    unsigned long orig_jiffies;
    int discon_flag = 0;

    if (!port)
        return;

    tty = port->port.tty;
    if (!tty)
        return;

    init_waitqueue_head(&wait);

    add_wait_queue(&port->write_wait, &wait);

    orig_jiffies = jiffies;

    while (1) {
        if ((jiffies - orig_jiffies) > timeout)
            break;

        if (port->disconnected)
            discon_flag = 1;

        if (!tty->driver_chars_in_buffer(tty))
            break;

        if (discon_flag)
            break;

        schedule_timeout_uninterruptible(HZ / 10);
    }

    remove_wait_queue(&port->write_wait, &wait);

    if (flush)
        tty->flush_chars(tty);

    if (!discon_flag) {
        while (tty->chars_in_buffer(tty)) {
            if ((jiffies - orig_jiffies) > timeout)
                break;

            schedule_timeout_uninterruptible(HZ / 10);
        }
    }
}

void edgeport_drain_data(struct edgeport_port *port, unsigned long timeout, int flush)
{
	struct tty_struct *tty = port->tty;
	DECLARE_WAITQUEUE(wait, current);
	unsigned long end_time;
	int draining = 1;
	int ret = 0;

	add_wait_queue(&tty->write_wait, &wait);

	end_time = jiffies + timeout;

	while (draining) {
		set_current_state(TASK_INTERRUPTIBLE);

		if (signal_pending(current) || time_after(jiffies, end_time))
			break;

		if (!port->connected) {
			draining = 0;
			break;
		}

		if (port->write_qlen == 0) {
			draining = 0;
			break;
		}

		schedule_timeout(1);
	}

	set_current_state(TASK_RUNNING);
	remove_wait_queue(&tty->write_wait, &wait);

	if (flush)
		port->write_qlen = 0;

	if (port->connected) {
		unsigned int baud = tty->termios.c_ospeed;
		unsigned long ticks = 0;

		if (baud != 0)
			ticks = (port->write_qlen * (1000000 / baud)) / 1000;

		end_time = jiffies + ticks;

		while (time_before(jiffies, end_time))
			schedule_timeout(1);
	}

	if (port->connected)
		port->write_qlen = 0;

	port->draining = 0;
	wake_up_interruptible(&port->drain_wait);
}
